    31→ * Returns both the manager (for external access) and the middleware function.
    32→ */
    33→export function projectContextMiddleware(options: ProjectContextMiddlewareOptions = {}) {
    34→  const manager = new ProjectContextManager(options.startupProject, options.pubsub);
    35→
    36→  // Register startup project if provided
    37→  // Note: Watcher will be started later after full initialization
    38→  if (options.startupProject) {
    39→    try {
    40→      manager.registerProject(options.startupProject, true);
    41→    } catch (error) {
    42→      console.warn(`[daemon] Failed to register startup project: ${error}`);
    43→    }
    44→  }
    45→
    46→  const middleware = (app: Elysia) =>
    47→    app
    48→      // Store manager in app state for WebSocket access
    49→      .state('projectManager', manager)
    50→      .derive(async ({ request, set }) => {
    51→        // Skip project context resolution for non-API routes (static files, SPA pages)
    52→        // and /api/health which should work without a project configured
    53→        const url = new URL(request.url, `http://${request.headers.get('host')}`);
    54→        const needsProject = url.pathname.startsWith('/api/')
    55→          && url.pathname !== '/api/health';
    56→        if (!needsProject) {
    57→          return { projectContext: undefined as unknown as ProjectContext };
    58→        }
    59→
    60→        try {
    61→          // AC: @multi-directory-daemon ac-1 - Extract X-Kspec-Dir header
    62→          const projectPath = request.headers.get('X-Kspec-Dir') || undefined;
    63→
    64→          let projectContext: ProjectContext;
    65→
    66→          if (projectPath) {
    67→            // AC: @multi-directory-daemon ac-1, ac-4, ac-5, ac-6, ac-7, ac-8, ac-8b, ac-8c
    68→            // Try to get existing or register new project
    69→            try {
    70→              projectContext = manager.getProject(projectPath);
    71→            } catch (err) {
    72→              // Not registered - try to register (ac-4: auto-register)
    73→              projectContext = manager.registerProject(projectPath);
    74→              // Start watcher asynchronously (don't block request)
    75→              void manager.startWatcher(projectPath).catch((watcherError) => {
    76→                console.error(`[daemon] Failed to start watcher for ${projectPath}:`, watcherError);
    77→              });
    78→            }
    79→          } else {
    80→            // AC: @multi-directory-daemon ac-2, ac-3, ac-20b
    81→            // No header - use default project
    82→            projectContext = manager.getProject();
    83→          }
    84→
    85→          return { projectContext };
    86→        } catch (err: unknown) {
    87→          const message = err instanceof Error ? err.message : String(err);
    88→
    89→          // AC: @multi-directory-daemon ac-3, ac-20b
    90→          if (
    91→            message.includes('No default project configured') ||
    92→            message.includes('Default project no longer valid')
    93→          ) {
    94→            set.status = 400;
    95→            return { error: message };
    96→          }
    97→
    98→          // AC: @multi-directory-daemon ac-5
    99→          if (message.includes('Invalid kspec project')) {
   100→            set.status = 400;
   101→            return { error: message };
   102→          }
   103→
   104→          // AC: @multi-directory-daemon ac-6
   105→          if (message.includes('Path must be absolute')) {
   106→            set.status = 400;
   107→            return { error: 'Path must be absolute' };
   108→          }
   109→
   110→          // AC: @multi-directory-daemon ac-7
   111→          if (message.includes('Path must not contain parent traversal')) {
   112→            set.status = 400;
   113→            return { error: 'Path must not contain parent traversal' };
   114→          }
   115→
   116→          // AC: @multi-directory-daemon ac-8b - permission denied
   117→          if (message.includes('Permission denied')) {
   118→            set.status = 403;
   119→            return { error: message };
   120→          }
   121→
   122→          // AC: @multi-directory-daemon ac-19 - OS resource limits
   123→          if (message.includes('Unable to watch project - resource limit reached')) {
   124→            set.status = 503;
   125→            return { error: message };
   126→          }
   127→
   128→          // Other errors
   129→          set.status = 500;
   130→          return { error: 'Internal server error' };
   131→        }
   132→      });
   133→
   134→  return { manager, middleware };
   135→}
   136→
